-const canonical = (helpful, harmful) =>
-  helpful + harmful > 0 ? helpful / (helpful + harmful) : null;
-
-const rows = db
-  .prepare(
-    `SELECT id, key, helpful, harmful, neutral, success_rate FROM knowledge_index`
